Ok then to do so, you could do a small custom widget like this:

``` js
var adWidget = {
  render: function(params) {
    var ids = params.results.hits.map(function(hit) { return hit.id });
    adWordsCallWith(ids);
  }
};

search.addWidget(adWidget);
